// Structured slot times (Scheduler V2 §4.3 — docs/scheduler-v2-ux.md).
//
// The editor works with structured {start, end} time parts; the wire value
// ("9AM-12PM") is GENERATED by `generateSlotValue` and is immutable once
// created — changing times means create-new + cascade-delete-old (DEF-1 and
// DEF-12). Parsing accepts the same inputs the storefront gate accepts
// (delivery-availability.ts `parseSlotTime`): `H(:MM)?(AM|PM)` per side, two
// sides joined by a dash. Generation always emits the canonical uppercase,
// space-free form so new values are byte-identical to the frozen defaults.

export interface SlotTimePart {
  /** 12-hour clock hour, 1–12. */
  hour: number;
  /** 0–59. */
  minute: number;
  meridiem: "AM" | "PM";
}

export interface SlotTimeRange {
  start: SlotTimePart;
  end: SlotTimePart;
}

const TIME_PART_PATTERN = /^(\d{1,2})(?::(\d{2}))?\s*(AM|PM)$/i;
const MINUTES_PER_DAY = 24 * 60;

function parseSlotTimePart(raw: string): SlotTimePart | null {
  const match = raw.trim().match(TIME_PART_PATTERN);
  if (!match) {
    return null;
  }

  const hour = Number(match[1]);
  const minute = Number(match[2] ?? "0");
  if (hour < 1 || hour > 12 || minute < 0 || minute > 59) {
    return null;
  }

  return {
    hour,
    minute,
    meridiem: match[3].toUpperCase() as "AM" | "PM",
  };
}

/**
 * Parse a stored slot value into structured times. Returns null for anything
 * the storefront availability gate would also fail to parse — those are the
 * live DEF-1 victims the UI must surface with a fix-or-delete prompt instead
 * of leaving silently unbookable.
 */
export function parseSlotValueToTimes(value: string): SlotTimeRange | null {
  const parts = typeof value === "string" ? value.split("-") : [];
  if (parts.length !== 2) {
    return null;
  }

  const start = parseSlotTimePart(parts[0]);
  const end = parseSlotTimePart(parts[1]);
  if (!start || !end) {
    return null;
  }

  return { start, end };
}

export function formatSlotTimePart(part: SlotTimePart): string {
  const minute =
    part.minute > 0 ? `:${String(part.minute).padStart(2, "0")}` : "";
  return `${part.hour}${minute}${part.meridiem}`;
}

/**
 * The one generator for wire values (§4.3). Output is asserted by test to be
 * byte-identical to the existing default-rules format for round-tripped
 * values ("9AM-12PM", "6PM-11PM", …).
 */
export function generateSlotValue(range: SlotTimeRange): string {
  return `${formatSlotTimePart(range.start)}-${formatSlotTimePart(range.end)}`;
}

/**
 * Minutes since local midnight; 12PM → 720. `position` disambiguates the 12AM
 * edge, which is minute 0 as a START but end-of-day (1440) as an END — without
 * it every window closing at midnight ("8PM-12AM", "11PM-12AM") reads as
 * inverted and is impossible to configure, even though the picker offers 12 +
 * AM as an end time.
 */
export function slotTimePartToMinutes(
  part: SlotTimePart,
  position: "start" | "end",
): number {
  let hour = part.hour % 12;
  if (part.meridiem === "PM") {
    hour += 12;
  }
  const minutes = hour * 60 + part.minute;
  return position === "end" && minutes === 0 ? MINUTES_PER_DAY : minutes;
}

export function isSlotRangeOrdered(range: SlotTimeRange): boolean {
  return (
    slotTimePartToMinutes(range.end, "end") >
    slotTimePartToMinutes(range.start, "start")
  );
}
